const QStringList colors{"black","pink","green","orange","yellow","purple","blue","red"};
const std::uint32_t rgb[]{0x1c2028,0xdf6c9c,0x55905a,0xd78b39,0xe7c84c,0x9467ac,0x567db8,0xbd5250};
