QString now(){return QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs);}
QString text(const QJsonObject& o,const char* key,int cap=256,bool allowEmpty=false){require(o[key].isString(),"product-string-required");auto s=o[key].toString();require((allowEmpty||!s.trimmed().isEmpty())&&s.size()<=cap&&!s.contains(QChar(0)),"product-string-invalid");return s;}
QString id(const QJsonObject& o,const char* key){auto s=text(o,key,128);require(QRegularExpression("^[A-Za-z0-9_-]+\\z").match(s).hasMatch(),"product-id-invalid");return s;}
QJsonObject layer(QString name="Ink"){return {{"id",newId()},{"name",name},{"visible",true},{"locked",false}};}
int byId(const QJsonArray& a,const QString& key){for(int i=0;i<a.size();++i)if(a[i].toObject()["id"].toString()==key)return i;return -1;}
QJsonObject contents(const QJsonObject& doc){QJsonObject result;for(auto key:{"layers","activeLayer","strokes","highlights","notes","layoutId"})result[key]=doc[key];return result;}
void restoreContents(QJsonObject& doc,const QJsonObject& source){for(auto key:{"layers","activeLayer","strokes","highlights","notes","layoutId"})doc[key]=source[key];}
/* Compact history keeps nested note changes proportional to the changed ink, with exact round-trip fallback. */
QJsonArray applyArray(QJsonArray from,const QJsonObject& e,bool forward){
 if(e.contains("b"))return forward?e["a"].toArray():e["b"].toArray();
 for(auto v:(forward?e["removed"]:e["added"]).toArray()){auto o=v.toObject()["o"].toObject();for(qsizetype k=0;k<from.size();++k)if(from[k].toObject()==o){from.removeAt(k);break;}}
 std::vector<std::pair<qsizetype,QJsonObject>> put;for(auto v:(forward?e["added"]:e["removed"]).toArray()){auto o=v.toObject();put.push_back({qsizetype(o["i"].toInteger()),o["o"].toObject()});}
 std::sort(put.begin(),put.end(),[](const auto& x,const auto& y){return x.first<y.first;});for(auto& [i,o]:put)from.insert(std::min(i,from.size()),o);
 for(auto v:e["patched"].toArray()){auto p=v.toObject();int at=byId(from,p["id"].toString());require(at>=0,"product-note-history-missing");auto n=from[at].toObject(),fields=p["fields"].toObject();for(auto f=fields.begin();f!=fields.end();++f){auto change=f.value().toObject();auto side=forward?"a":"b";if(change.contains(side))n[f.key()]=change[side];else n.remove(f.key());}if(p.contains("strokes"))n["strokes"]=applyArray(n["strokes"].toArray(),p["strokes"].toObject(),forward);from[at]=n;}return from;}
QJsonObject arrayDelta(const QJsonArray& b,const QJsonArray& a,bool notes=false){
 QHash<QString,qsizetype> bi,ai;for(qsizetype i=0;i<b.size();++i){auto key=b[i].toObject()["id"].toString();if(!key.isEmpty())bi.insert(key,i);}for(qsizetype i=0;i<a.size();++i){auto key=a[i].toObject()["id"].toString();if(!key.isEmpty())ai.insert(key,i);}
 QJsonArray removed,added,patched;
 for(qsizetype i=0;i<b.size();++i){auto o=b[i].toObject();auto f=ai.find(o["id"].toString());if(o["id"].toString().isEmpty()||f==ai.end()||(!notes&&a[*f]!=b[i]))removed.append(QJsonObject{{"i",double(i)},{"o",o}});}
 for(qsizetype i=0;i<a.size();++i){auto o=a[i].toObject();auto f=bi.find(o["id"].toString());if(o["id"].toString().isEmpty()||f==bi.end()||(!notes&&b[*f]!=a[i]))added.append(QJsonObject{{"i",double(i)},{"o",o}});
  else if(notes&&b[*f]!=a[i]){auto old=b[*f].toObject();QJsonObject p{{"id",o["id"]}},fields;QSet<QString> keys;for(auto k=old.begin();k!=old.end();++k)keys.insert(k.key());for(auto k=o.begin();k!=o.end();++k)keys.insert(k.key());
   for(auto key:keys)if(old.value(key)!=o.value(key)){if(key=="strokes"&&old[key].isArray()&&o[key].isArray())p[key]=arrayDelta(old[key].toArray(),o[key].toArray());else{QJsonObject field;if(old.contains(key))field["b"]=old[key];if(o.contains(key))field["a"]=o[key];fields[key]=field;}}if(!fields.isEmpty())p["fields"]=fields;patched.append(p);}}
 QJsonObject e{{"removed",removed},{"added",added}};if(!patched.isEmpty())e["patched"]=patched;if(applyArray(b,e,true)!=a||applyArray(a,e,false)!=b)e=QJsonObject{{"b",b},{"a",a}};return e;}
QJsonObject delta(const QJsonObject& before,const QJsonObject& after){QJsonObject d;
 for(auto key:{"activeLayer","layoutId","layers"})if(before[key]!=after[key])d[key]=QJsonObject{{"b",before[key]},{"a",after[key]}};
 for(auto key:{"strokes","highlights","notes"})if(before[key]!=after[key])d[key]=arrayDelta(before[key].toArray(),after[key].toArray(),QString(key)=="notes");return d;}
void applyDelta(QJsonObject& doc,const QJsonObject& d,bool forward){for(auto i=d.begin();i!=d.end();++i){auto e=i.value().toObject();if(i.key()=="strokes"||i.key()=="highlights"||i.key()=="notes")doc[i.key()]=applyArray(doc[i.key()].toArray(),e,forward);else doc[i.key()]=forward?e["a"]:e["b"];}}
QJsonObject strokeAnchor(const QJsonObject& source){QJsonObject anchor;for(auto key:{"document","revision","format","page","pageId","layoutId","viewId","version","scope"})if(source.contains(key))anchor[key]=source[key];return anchor;}
QJsonObject slimStroke(QJsonObject s){if(s["anchor"].isObject())s["anchor"]=strokeAnchor(s["anchor"].toObject());return s;}
QJsonArray slimStrokes(QJsonArray a){for(qsizetype i=0;i<a.size();++i)a[i]=slimStroke(a[i].toObject());return a;}
QJsonObject slimNote(QJsonObject n){if(n["strokes"].isArray())n["strokes"]=slimStrokes(n["strokes"].toArray());return n;}
QJsonArray slimNotes(QJsonArray a){for(qsizetype i=0;i<a.size();++i)a[i]=slimNote(a[i].toObject());return a;}
QJsonObject slimArrayHistory(QJsonObject e,bool notes){for(auto side:{"b","a"})if(e.value(side).isArray())e[side]=notes?slimNotes(e[side].toArray()):slimStrokes(e[side].toArray());for(auto side:{"removed","added"})if(e.value(side).isArray()){auto a=e[side].toArray();for(qsizetype i=0;i<a.size();++i){auto item=a[i].toObject();item["o"]=notes?slimNote(item["o"].toObject()):slimStroke(item["o"].toObject());a[i]=item;}e[side]=a;}
 if(notes&&e.value("patched").isArray()){auto a=e["patched"].toArray();for(qsizetype i=0;i<a.size();++i){auto p=a[i].toObject();if(p.value("strokes").isObject())p["strokes"]=slimArrayHistory(p["strokes"].toObject(),false);auto fields=p.value("fields").toObject();if(fields.value("strokes").isObject()){auto pair=fields["strokes"].toObject();for(auto side:{"b","a"})if(pair.value(side).isArray())pair[side]=slimStrokes(pair[side].toArray());fields["strokes"]=pair;p["fields"]=fields;}a[i]=p;}e["patched"]=a;}return e;}
QJsonObject slimHistory(QJsonObject e){for(auto side:{"before","after"})if(e.value(side).isObject()){auto c=e[side].toObject();if(c.value("notes").isArray())c["notes"]=slimNotes(c["notes"].toArray());e[side]=c;}if(e.value("delta").isObject()){auto d=e["delta"].toObject();if(d.value("notes").isObject())d["notes"]=slimArrayHistory(d["notes"].toObject(),true);e["delta"]=d;}return e;}
/* A shared 4 MiB budget bounds both undo and redo. Drop the farthest entries, never a hole in the chain. */
void compact(QJsonObject& state,bool normalize=true){auto doc=state["annotation"].toObject();if(doc.isEmpty())return;if(normalize)doc["notes"]=slimNotes(doc["notes"].toArray());auto undo=doc["undo"].toArray(),redo=doc["redo"].toArray();qint64 bytes=4;std::vector<qint64> ub,rb;
 auto scan=[&](QJsonArray& history,std::vector<qint64>& sizes){for(qsizetype i=0;i<history.size();++i){auto e=normalize?slimHistory(history[i].toObject()):history[i].toObject();if(normalize)history[i]=e;auto size=QJsonDocument(e).toJson(QJsonDocument::Compact).size()+1;sizes.push_back(size);bytes+=size;}};scan(undo,ub);scan(redo,rb);int expired=0;std::size_t u=0,r=0;
 while(u<ub.size()&&(bytes>4*1024*1024||undo.size()>32)){bytes-=ub[u++];undo.removeAt(0);++expired;}while(r<rb.size()&&(bytes>4*1024*1024||redo.size()>32)){bytes-=rb[r++];redo.removeAt(0);++expired;}
 doc["undo"]=undo;doc["redo"]=redo;if(expired)doc["undoExpired"]=doc["undoExpired"].toInteger()+expired;state["annotation"]=doc;}
void normalizeStore(Store& store){if(store.notesNormalization().verified)return;auto before=store.snapshot(),candidate=before;compact(candidate);auto revision=before.value("revision");if(candidate!=before)store.transaction([&](QJsonObject& state){if(state.value("revision")==before.value("revision"))state=candidate;else compact(state);revision=state.value("revision").toDouble()+1;});store.markNotesNormalized(revision);}
void journal(QJsonObject& doc,const QJsonObject& before,const QString& label){auto after=contents(doc);if(before==after)return;auto history=doc["undo"].toArray();if(history.size()==32){history.removeAt(0);doc["undoExpired"]=doc["undoExpired"].toInteger()+1;}history.append(QJsonObject{{"label",label},{"delta",delta(before,after)}});doc["undo"]=history;doc["redo"]=QJsonArray{};}
void editable(const QJsonObject& doc,const QString& layerId){auto layers=doc["layers"].toArray();auto i=byId(layers,layerId);require(i>=0,"product-layer-missing");auto l=layers[i].toObject();require(l["visible"].toBool()&&!l["locked"].toBool(),"product-layer-hidden-or-locked");}
void validAnchor(const QJsonObject& anchor,const QJsonObject& doc){require(semantic::validAnchorSegments(anchor),"product-anchor-segments");require(compatiblePage(doc,anchor),"product-anchor-identity");auto quads=anchor["quads"].toArray();require(quads.size()<=8192,"product-anchor-quad-capacity");for(auto q:quads){auto a=q.toArray();require(a.size()==8,"product-anchor-quad");for(auto v:a)require(v.isDouble()&&std::isfinite(v.toDouble())&&std::abs(v.toDouble())<100000,"product-anchor-quad-value");}}
QJsonObject checkedStroke(QJsonObject stroke,const QJsonObject& doc){auto layerId=id(stroke,"layer");editable(doc,layerId);validateStyle(stroke["style"].toObject());(void)fillOpacity(stroke);validAnchor(stroke["anchor"].toObject(),doc);auto points=stroke["points"].toArray();require(!points.isEmpty()&&points.size()<=8192,"product-stroke-points-capacity");for(auto p:points){auto a=p.toArray();require(a.size()==2||a.size()==3,"product-stroke-point-schema");for(auto v:a)require(v.isDouble()&&std::isfinite(v.toDouble())&&std::abs(v.toDouble())<=100000,"product-stroke-point-invalid");if(a.size()==3)require(a[2].toDouble()>=0&&a[2].toDouble()<=1,"product-stroke-pressure-invalid");}if(!stroke.contains("id"))stroke["id"]=newId();id(stroke,"id");stroke["created"]=now();return stroke;}

